verus! {
    /// Returns the maximum element of a non‐empty slice of integers.
    ///
    /// Requires:
    ///     `a.len() >= 1`
    /// Ensures:
    ///     For all valid indices `i`, `a[i] <= m`.
    ///     There exists at least one index `j` with `a[j] == m`.
    fn maxArray(a: &[int]) -> (m: int)
        requires
            a.len() >= 1,
        ensures
            forall |i: usize| i < a.len() ==> a[i] <= m,
        ensures
            exists |j: usize| j < a.len() && a[j] == m,
    {
        // Initialize the current maximum to the first element.
        let mut m: int = a[0];
        // We will scan from index 1 up to a.len().
        let mut idx: usize = 1;

        // Loop invariant:
        //   1) idx ≤ a.len()
        //   2) for all i < idx, a[i] ≤ m
        //   3) there exists j < idx with a[j] == m
        // We decrease (a.len() - idx) on each iteration.
        while idx < a.len()
            invariant
                idx <= a.len(),
                forall |i: usize| i < idx ==> a[i] <= m,
                exists |j: usize| j < idx && a[j] == m,
            decreases
                a.len() - idx,
        {
            let cur: int = a[idx];
            // If the current element is greater than the current maximum,
            // update the maximum.
            if cur > m {
                m = cur;
            }
            idx = idx + 1;
        }

        // At loop exit, idx == a.len(), so the invariants give
        // exactly the desired post‐conditions.
        m
    }
}

